const ordered = $input.all()
  .map((item, inputIndex) => ({ item, inputIndex }))
  .filter(({ item }) => item.json?.status === 'CONCEPT_APPROVED')
  .sort((a, b) => {
    const aRow = Number(a.item.json.row_number);
    const bRow = Number(b.item.json.row_number);
    const aHasRow = Number.isFinite(aRow);
    const bHasRow = Number.isFinite(bRow);
    if (aHasRow && bHasRow && aRow !== bRow) return aRow - bRow;
    if (aHasRow !== bHasRow) return aHasRow ? -1 : 1;
    const storyOrder = String(a.item.json.storyId ?? '').localeCompare(String(b.item.json.storyId ?? ''));
    return storyOrder || a.inputIndex - b.inputIndex;
  });

const classifyCandidate = ({ item, inputIndex }) => {
  const story = item.json;
  const marker = String(story.canonInitializationState ?? '').trim();
  const canonVersion = String(story.canonVersion ?? '').trim();
  const canonRef = String(story.canonRef ?? '').trim();
  const blankLineage = canonVersion === '' && canonRef === '';
  const validLineage =
    /^canon-v[0-9]+\.[0-9]+$/.test(canonVersion) &&
    /^[0-9a-f]{40}$/i.test(canonRef);

  let outlineCandidateOutcome = 'INTEGRITY_FAILURE';
  if (marker === '' && blankLineage) {
    outlineCandidateOutcome = 'PRE_CANON_LEGACY';
  } else if (validLineage && (marker === '' || marker === 'ASSIGNED')) {
    outlineCandidateOutcome = 'ELIGIBLE';
  }

  return { item, inputIndex, outlineCandidateOutcome };
};

const classified = ordered.map(classifyCandidate);
const selected =
  classified.find((candidate) => candidate.outlineCandidateOutcome === 'ELIGIBLE') ??
  classified.find((candidate) => candidate.outlineCandidateOutcome === 'INTEGRITY_FAILURE');

if (!selected) return [];

const eligible = selected.outlineCandidateOutcome === 'ELIGIBLE';
return [{
  json: {
    ...selected.item.json,
    outlineCandidateEligible: eligible,
    outlineCandidateOutcome: selected.outlineCandidateOutcome,
    errorCode: eligible ? '' : 'CANON_LINEAGE_INVALID',
    message: eligible
      ? ''
      : 'CONCEPT_APPROVED Story canon initialization marker/lineage is malformed or conflicting. Outline generation was not attempted.',
    selectionFailureNode: 'Select Eligible Outline Story',
    selectionFailureNodeType: 'n8n-nodes-base.code',
  },
  pairedItem: { item: selected.inputIndex },
}];

